insert into public.book_quiz (book_key, book_title, tier, question, options, answer, explanation) values
('les mains du miracle', 'Les mains du miracle', 50, 'Quel dignitaire nazi Félix Kersten soigne-t-il grâce à ses massages ?', '["Himmler","Goebbels","Goering","Hess"]'::jsonb, 0, 'Le masseur finlandais Félix Kersten soulage les douleurs d''estomac d''Heinrich Himmler. Cette relation de confiance lui donne un pouvoir d''influence rare.'),
('les mains du miracle', 'Les mains du miracle', 100, 'Que cherche Kersten à obtenir de Himmler en échange de ses soins ?', '["Un poste dans le gouvernement","La libération de détenus","Une forte somme en or","Un passeport pour la Suède"]'::jsonb, 1, 'Kersten négocie la libération de nombreux détenus, dont des Juifs et des Scandinaves. Le roman de Kessel s''appuie sur cette histoire vraie.'),
('dans son silence', 'Dans son silence', 50, 'Quel est le métier de Theo Faber ?', '["Médecin légiste","Psychothérapeute","Avocat pénaliste","Journaliste d''enquête"]'::jsonb, 1, 'Theo, psychothérapeute, obtient un poste à la clinique où est internée Alicia Berenson. Il veut la faire parler après sa condamnation pour le meurtre de son mari.'),
('dans son silence', 'Dans son silence', 100, 'Qui a réellement tué Gabriel, le mari d''Alicia ?', '["Theo Faber","Le frère d''Alicia","Alicia elle-même","Kathy"]'::jsonb, 0, 'Theo, obsédé par Alicia, a organisé les événements et commis le meurtre. Son journal retrouvé par Alicia dévoile le piège.'),
('the silent patient', 'The Silent Patient', 50, 'Quel est le métier de Theo Faber ?', '["Médecin légiste","Psychothérapeute","Avocat pénaliste","Journaliste d''enquête"]'::jsonb, 1, 'Theo, psychothérapeute, obtient un poste à la clinique où est internée Alicia Berenson. Il veut la faire parler après sa condamnation pour le meurtre de son mari.'),
('the silent patient', 'The Silent Patient', 100, 'Qui a réellement tué Gabriel, le mari d''Alicia ?', '["Theo Faber","Le frère d''Alicia","Alicia elle-même","Kathy"]'::jsonb, 0, 'Theo, obsédé par Alicia, a organisé les événements et commis le meurtre. Son journal retrouvé par Alicia dévoile le piège.'),
('dark matter', 'Dark Matter', 50, 'Quel est le métier de Jason Dessen au début du roman ?', '["Journaliste scientifique","Professeur de physique","Policier de Chicago","Médecin urgentiste"]'::jsonb, 1, 'Jason mène une vie tranquille à Chicago avec sa femme Daniela et son fils, après avoir renoncé à une grande carrière scientifique. Cette vie est bouleversée par son enlèvement.'),
('replay', 'Replay', 50, 'Que se passe-t-il quand Jeff Winston meurt à 43 ans ?', '["Il devient un fantôme qui hante sa famille","Il revit sa vie à 18 ans, avec ses souvenirs","Il meurt pour de bon et le roman s''arrête","Il se réveille dans un corps du futur"]'::jsonb, 1, 'Jeff revit sa vie depuis 1963 avec toutes ses connaissances. Il comprend que ce cycle peut se répéter à chaque mort.'),
('l enigme de la chambre 622', 'L''énigme de la chambre 622', 50, 'Dans quel cadre se déroule le meurtre non résolu qui sert de fil rouge à l''intrigue ?', '["Un train de nuit","Un hôtel de luxe à Verbier","Une clinique suisse","Un château en Normandie"]'::jsonb, 1, 'Un meurtre a eu lieu au Palace de Verbier, dans la chambre 622, sans que personne ne soit jamais identifié. Le narrateur enquête avec Scarlett.'),
('inconnu a cette adresse', 'Inconnu à cette adresse', 100, 'Comment Max se venge-t-il de Martin, qui l''a abandonné sous le nazisme ?', '["En le dénonçant lui-même à la Gestapo","En l''attaquant en justice après la guerre","En écrivant des lettres qui alertent la censure","En faisant disparaître sa famille par des complices"]'::jsonb, 2, 'Max, juif, écrit à Martin des lettres codées qui alertent la censure nazie. Martin, compromis, finit par voir ses lettres revenir : « destinataire inconnu ».'),
('je suis une legende', 'Je suis une légende', 100, 'Que comprend Robert Neville à la fin du roman ?', '["Que le virus a enfin disparu d''Amérique","Qu''il est immunisé et peut tous les sauver","Qu''il est le monstre de la nouvelle société","Que sa femme est encore en vie quelque part"]'::jsonb, 2, 'Neville a tué de nombreux infectés qui forment désormais une société organisée : il en est le « monstre ». Il accepte son sort et devient la légende du titre.'),
('i am legend', 'I Am Legend', 100, 'Que comprend Robert Neville à la fin du roman ?', '["Que le virus a enfin disparu d''Amérique","Qu''il est immunisé et peut tous les sauver","Qu''il est le monstre de la nouvelle société","Que sa femme est encore en vie quelque part"]'::jsonb, 2, 'Neville a tué de nombreux infectés qui forment désormais une société organisée : il en est le « monstre ». Il accepte son sort et devient la légende du titre.'),
('petit pays', 'Petit pays', 50, 'Dans quel pays Gabriel, le narrateur, passe-t-il son enfance ?', '["Kenya","Congo","Burundi","Rwanda"]'::jsonb, 2, 'Gabriel vit au Burundi, dans une enclave d''enfance heureuse, jusqu''à la guerre civile qui éclate dans la région. Son père est français et sa mère rwandaise.'),
('rhinoceros', 'Rhinocéros', 50, 'Que deviennent peu à peu les habitants de la ville ?', '["Des fantômes","Des animaux sauvages","Des rhinocéros","Des statues"]'::jsonb, 2, 'La « rhinocérite » transforme les habitants en rhinocéros, par conformisme. Bérenger, lui, s''interroge devant ce mal contagieux.'),
('rhinoceros', 'Rhinocéros', 100, 'Que décide Bérenger à la fin ?', '["De résister seul, sans jamais capituler","De se transformer pour rejoindre Daisy","De suivre les autres dans leur métamorphose","De s''enfuir de la ville en voiture"]'::jsonb, 0, 'Resté le dernier homme, Bérenger crie qu''il ne capitulera pas. Ionesco met en scène la résistance à la pensée unique.'),
('un sac de billes', 'Un sac de billes', 50, 'Pourquoi le père de Joseph et Maurice les envoie-t-il seuls loin de Paris ?', '["Pour leur offrir des vacances au soleil","Pour qu''ils travaillent dans une ferme","Pour qu''ils poursuivent leurs études","Pour les mettre à l''abri des rafles"]'::jsonb, 3, 'Dans la France occupée, être juif devient dangereux : le père confie à ses fils la mission de fuir vers la zone libre. Les deux enfants se débrouillent seuls.'),
('l enfant de noe', 'L''Enfant de Noé', 50, 'Qui cache Joseph, enfant juif, pendant l''Occupation en Belgique ?', '["Le père Pons, un prêtre","Un instituteur du village","Un rabbin de Bruxelles","Un fermier des environs"]'::jsonb, 0, 'Le père Pons accueille Joseph et d''autres enfants sous de fausses identités. Il y risque sa vie.'),
('la defense lincoln', 'La Défense Lincoln', 50, 'D''où Mickey Haller dirige-t-il son cabinet d''avocat ?', '["De son appartement de Los Angeles","D''un grand bureau en centre-ville","D''un café en face du palais de justice","De la banquette arrière de sa Lincoln"]'::jsonb, 3, 'Mickey, avocat pénaliste, passe ses journées entre tribunaux et prisons, dans une Lincoln avec chauffeur. L''affaire d''un riche héritier va tout bouleverser.'),
